import React from 'react';
import { Route, Switch } from 'react-router-dom';

import Home from '../pages/Home';
import Catalog from '../pages/Catalog';
import Detail from '../pages/Detail';

const Routes = () => {
  return (
    <Switch>
      {/* Route for Genre View */}
      <Route
        path='/:home/:category/genre/:genreName'
        render={(props) => <Catalog {...props} isGenre={true} />}
      />

      {/* Route for Search View */}
      <Route
        path='/:home/:category/search/:keyword'
        component={Catalog}
      />

      {/* Route for standard Category View (Movies/TV) */}
      <Route
        path='/:home/:category'
        component={Catalog}
      />

      {/* Detail page route */}
      <Route
        path='/:home/:category/:id'
        component={Detail}
      />

      {/* Home page route */}
      <Route
        path='/:home'
        component={Home}
      />
    </Switch>
  );
};

export default Routes;
